const incoming = $input.first().json;
let request = incoming.body ?? incoming;
if (Array.isArray(request) && request.length === 1) request = request[0];
if (!request || typeof request !== 'object' || Array.isArray(request)) {
  throw new Error('Webhook body must contain one RNE-validation request');
}
return [{ json: request }];

// n8n Code node: Run Once for All Items.
const request = $input.first().json;
const normalization = request.normalization;
const policy = request.official_validation;

if (!normalization || typeof normalization !== 'object' || !Array.isArray(normalization.companies)) {
  throw new Error('RNE validation requires a normalization object with companies');
}
if (!policy || typeof policy !== 'object') throw new Error('RNE validation requires official_validation policy');
if (typeof policy.enabled !== 'boolean') throw new Error('official_validation.enabled must be boolean');
if (!['WHEN_IDENTIFIER_AVAILABLE', 'REQUIRED_BEFORE_READY', 'MANUAL_ONLY'].includes(policy.mode)) {
  throw new Error(`Unsupported official-validation mode: ${policy.mode}`);
}
if (!['CONTINUE_PARTIAL', 'REVIEW', 'BLOCK_READINESS'].includes(policy.failure_policy)) {
  throw new Error(`Unsupported RNE failure policy: ${policy.failure_policy}`);
}
if (normalization.companies.length === 0) throw new Error('RNE validation received no companies');

return normalization.companies.map((company) => ({
  json: {
    campaign_id: normalization.campaign_id,
    company_id: company.company_id,
    canonical_name: company.canonical_name,
    identifier: company.legal_identifier,
    validation_policy: policy,
    company,
    normalization_status: normalization.status,
    normalization_warnings: normalization.warnings ?? [],
  },
}));

// n8n Code node: Run Once for Each Item.
return {
  json: {
    contract_version: '1.0',
    campaign_id: $json.campaign_id,
    company_id: $json.company_id,
    canonical_name: $json.canonical_name,
    identifier: $json.identifier,
    validation_policy: $json.validation_policy,
  },
};

// n8n Code node: Run Once for Each Item.
const expected = $('Build RNE Connector Request').item.json;
const result = $json;
if (result && result.error) {
  return { json: {
    campaign_id: expected.campaign_id,
    company_id: expected.company_id,
    provider: 'RNE',
    status: 'UNAVAILABLE',
    conflicts: [],
    warnings: [`RNE connector unavailable: ${result.error.message ?? 'request failed'}`],
  }};
}
const statuses = new Set([
  'NOT_REQUESTED', 'SKIPPED_NO_IDENTIFIER', 'VERIFIED',
  'NOT_FOUND', 'CONFLICT', 'UNAVAILABLE',
]);
for (const field of ['campaign_id', 'company_id', 'provider', 'status']) {
  if (typeof result[field] !== 'string' || !result[field]) throw new Error(`RNE response requires ${field}`);
}
if (result.campaign_id !== expected.campaign_id || result.company_id !== expected.company_id) {
  throw new Error('RNE connector changed a controlled identifier');
}
if (result.provider !== 'RNE' || !statuses.has(result.status)) {
  throw new Error(`Invalid RNE provider or status: ${result.status}`);
}
if (!Array.isArray(result.conflicts) || !Array.isArray(result.warnings)) {
  throw new Error('RNE response requires conflicts and warnings arrays');
}
if (result.status === 'VERIFIED' && (!result.official_fields || !result.validated_at)) {
  throw new Error('VERIFIED RNE response requires official fields and validation timestamp');
}
return { json: result };

// n8n Code node: Run Once for All Items.
const responses = $input.all().map((item) => item.json);
const tasks = $('Prepare RNE Validation Tasks').all().map((item) => item.json);
if (responses.length !== tasks.length) throw new Error('RNE response count does not match company count');

const taskByCompany = new Map(tasks.map((task) => [task.company_id, task]));
const responseByCompany = new Map(responses.map((response) => [response.company_id, response]));
const policy = tasks[0].validation_policy;
const reviewItems = [];

function shouldReview(status) {
  if (status === 'CONFLICT') return true;
  if (policy.mode === 'MANUAL_ONLY' && status === 'NOT_REQUESTED') return true;
  return policy.failure_policy === 'REVIEW' && ['NOT_FOUND', 'UNAVAILABLE'].includes(status);
}

function readyForScoring(status) {
  if (status === 'VERIFIED') return true;
  if (status === 'CONFLICT') return false;
  if (policy.mode === 'REQUIRED_BEFORE_READY') return false;
  if (policy.failure_policy === 'BLOCK_READINESS' && !['SKIPPED_NO_IDENTIFIER', 'NOT_REQUESTED'].includes(status)) return false;
  return true;
}

const companies = tasks.map((task) => {
  const validation = responseByCompany.get(task.company_id);
  if (!validation) throw new Error(`Missing RNE response for ${task.company_id}`);
  const reviewRequired = shouldReview(validation.status);
  const ready = readyForScoring(validation.status);
  if (reviewRequired) {
    reviewItems.push({
      review_item_id: `rne_review_${task.company_id}`,
      company_id: task.company_id,
      type: policy.mode === 'MANUAL_ONLY' ? 'MANUAL_RNE_VALIDATION' : `RNE_${validation.status}`,
      priority: validation.status === 'CONFLICT' ? 'HIGH' : 'NORMAL',
      status: 'OPEN',
      conflicts: validation.conflicts,
    });
  }
  return {
    ...task.company,
    official_validation: validation,
    ready_for_scoring: ready,
    review_required: Boolean(task.company.review_required || reviewRequired),
  };
});

const counts = Object.fromEntries([
  'NOT_REQUESTED', 'SKIPPED_NO_IDENTIFIER', 'VERIFIED', 'NOT_FOUND', 'CONFLICT', 'UNAVAILABLE',
].map((status) => [status.toLocaleLowerCase(), responses.filter((response) => response.status === status).length]));
const blockedCount = companies.filter((company) => !company.ready_for_scoring).length;
let status = 'COMPLETED';
if (reviewItems.length) status = 'REVIEW_REQUIRED';
else if (blockedCount) status = 'PARTIAL';

const warnings = [...new Set([
  ...(tasks[0].normalization_warnings ?? []),
  ...responses.flatMap((response) => response.warnings ?? []),
])];

return [{
  json: {
    contract_version: '1.0',
    campaign_id: tasks[0].campaign_id,
    status,
    provider: 'RNE',
    policy,
    company_count: companies.length,
    counts,
    ready_for_scoring_count: companies.length - blockedCount,
    blocked_from_scoring_count: blockedCount,
    review_required_count: reviewItems.length,
    companies,
    review_items: reviewItems,
    warnings,
  },
}];

// n8n Code node: Run Once for Each Item.
const result = $json;
if (result.contract_version !== '1.0' || typeof result.campaign_id !== 'string') throw new Error('Invalid RNE validation contract');
if (!['COMPLETED', 'PARTIAL', 'REVIEW_REQUIRED'].includes(result.status)) throw new Error(`Invalid aggregate RNE status: ${result.status}`);
if (!Array.isArray(result.companies) || !Array.isArray(result.review_items) || !Array.isArray(result.warnings)) {
  throw new Error('RNE validation result requires companies, review_items, and warnings');
}
if (result.company_count !== result.companies.length) throw new Error('RNE company count is inconsistent');
if (result.ready_for_scoring_count + result.blocked_from_scoring_count !== result.company_count) {
  throw new Error('RNE readiness counts are inconsistent');
}
for (const company of result.companies) {
  if (!company.official_validation || company.official_validation.provider !== 'RNE') throw new Error('Company is missing RNE validation envelope');
  if (typeof company.ready_for_scoring !== 'boolean') throw new Error('Company is missing readiness decision');
}
return { json: result };
